import React, { useState, useEffect, useMemo } from 'react';
import { pricingApi } from '../api/pricingApi';
import { ItemPriceHistory } from '../types';
import { SearchableSelect } from '../components/ui';
import { BRAND } from '../constants';

interface MonthDef {
  name: string;
  monthIdx: number;
  year: number;
}

interface QuarterDef {
  quarterStr: string;
  year: number;
  qIndex: number;
  revisionStr: string;
  months: MonthDef[];
}

interface GroupedItem {
  key: string;
  foreignName: string;
  castingCode: string;
  itemDescription: string;
  vendor: string;
  grade: string;
  domesticExport?: string;
  quarters: Record<string, {
    months: Record<string, ItemPriceHistory | null>;
    revision: ItemPriceHistory | null;
    prevRevision: ItemPriceHistory | null;
  }>;
}

const getMonthShortName = (monthIdx: number) => {
  return ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"][monthIdx];
};

const getYearMonthVal = (dateStr: string | Date | null | undefined): number => {
  if (!dateStr) return 0;
  const d = new Date(dateStr);
  return d.getFullYear() * 100 + d.getMonth();
};

const getQuartersData = (startYear?: number, startQuarter?: number): QuarterDef[] => {
  const quarters: QuarterDef[] = [];
  const d = new Date();
  if (startYear && startQuarter) {
    const month = (startQuarter * 3) - 1;
    d.setFullYear(startYear);
    d.setMonth(month);
  }
  for (let i = 0; i < 4; i++) {
    const qIndex = Math.floor(d.getMonth() / 3) + 1;
    const year = d.getFullYear();
    const yy = year.toString().slice(-2);
    let nextQIndex = qIndex + 1;
    let nextYear = year;
    if (nextQIndex > 4) { nextQIndex = 1; nextYear += 1; }
    const startMonth = (qIndex - 1) * 3;
    const months = [
      { name: `${getMonthShortName(startMonth)}-${yy}`, monthIdx: startMonth, year },
      { name: `${getMonthShortName(startMonth + 1)}-${yy}`, monthIdx: startMonth + 1, year },
      { name: `${getMonthShortName(startMonth + 2)}-${yy}`, monthIdx: startMonth + 2, year },
    ];
    quarters.push({ quarterStr: `Quarter ${qIndex}`, year, qIndex, revisionStr: `MMR/ Revision Quarter ${nextQIndex} ${nextYear}`, months });
    d.setMonth(d.getMonth() - 3);
  }
  return quarters.reverse();
};

export const PriceHistoryPage: React.FC = () => {
  const [mode, setMode] = useState<'vendor' | 'customer'>('vendor');
  const [history, setHistory] = useState<ItemPriceHistory[]>([]);
  const [loading, setLoading] = useState(false);
  const [castingCodeFilter, setCastingCodeFilter] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [vendorFilter, setVendorFilter] = useState('');
  const [customerFilter, setCustomerFilter] = useState('');
  const [expandedMonths, setExpandedMonths] = useState<Set<string>>(new Set());

  const currentYear = new Date().getFullYear();
  const currentQuarter = Math.floor(new Date().getMonth() / 3) + 1;
  const [startYear, setStartYear] = useState<number>(currentYear);
  const [startQuarter, setStartQuarter] = useState<number>(currentQuarter);

  const [vendorFiltersData, setVendorFiltersData] = useState<{ castingCodes: string[]; itemCodes: string[]; vendors: { id: string; name: string }[] }>({ castingCodes: [], itemCodes: [], vendors: [] });
  const [customerFiltersData, setCustomerFiltersData] = useState<{ castingCodes: string[]; customers: { code: string; name: string }[] }>({ castingCodes: [], customers: [] });

  const castingCodes = mode === 'customer' ? customerFiltersData.castingCodes : vendorFiltersData.castingCodes;

  const loadFilters = async (m: 'vendor' | 'customer') => {
    try {
      const res = await pricingApi.getPriceLogFilters(m);
      if (m === 'customer') setCustomerFiltersData(res || { castingCodes: [], customers: [] });
      else setVendorFiltersData(res || { castingCodes: [], itemCodes: [], vendors: [] });
    } catch (err) { console.error(err); }
  };

  const loadHistory = async (m: 'vendor' | 'customer', ccFilter: string, vFilter: string, custFilter: string) => {
    setLoading(true);
    try {
      const res = m === 'customer'
        ? await pricingApi.getPriceLog(ccFilter, '', '', 'customer', custFilter)
        : await pricingApi.getPriceLog(ccFilter, '', vFilter, 'vendor');
      if (res) setHistory(res);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  };

  useEffect(() => { loadFilters('vendor'); loadFilters('customer'); }, []);

  useEffect(() => {
    setCastingCodeFilter(''); setVendorFilter(''); setCustomerFilter(''); setHistory([]);
    loadHistory(mode, '', '', '');
  }, [mode]);

  useEffect(() => {
    loadHistory(mode, castingCodeFilter, vendorFilter, customerFilter);
  }, [castingCodeFilter, vendorFilter, customerFilter]);

  const quartersList = useMemo(() => getQuartersData(startYear, startQuarter), [startYear, startQuarter]);

  const groupedData = useMemo(() => {
    const groups: Record<string, GroupedItem> = {};
    const sortedHistory = [...history].sort((a, b) => new Date(a.createdAt || '').getTime() - new Date(b.createdAt || '').getTime());

    const getKey = (log: ItemPriceHistory) => {
      if (mode === 'customer') {
        return `${log.castingCode || '-'}|${log.customerCode || log.customerName || '-'}`;
      }
      return `${log.vendorId || log.vendorName || '-'}|${log.castingCode || '-'}|${log.grade || '-'}|${log.customerName || '-'}|${log.itemDescription || '-'}|${log.machineType || '-'}|${log.coating || '-'}|${log.cavity || '-'}|${log.coreSleeve || '-'}`;
    };

    sortedHistory.forEach(log => {
      const key = getKey(log);
      if (!groups[key]) {
        groups[key] = {
          key,
          foreignName: log.customerName || '-',
          castingCode: log.castingCode || '-',
          itemDescription: log.itemDescription || '-',
          vendor: mode === 'customer' ? (log.customerApprovalFoundry || log.customerName || '-') : (log.vendorName || log.vendorId || '-'),
          grade: log.grade || '-',
          domesticExport: log.domesticExport,
          quarters: {},
        };
      }
    });

    const logsByKey: Record<string, ItemPriceHistory[]> = {};
    sortedHistory.forEach(log => {
      const key = getKey(log);
      if (!logsByKey[key]) logsByKey[key] = [];
      logsByKey[key].push(log);
    });

    const finalGroups = Object.values(groups).map(g => {
      const finalQuarters: Record<string, any> = {};
      const itemLogs = logsByKey[g.key] || [];

      quartersList.forEach(qDef => {
        const monthsData: Record<string, ItemPriceHistory | null> = {};
        qDef.months.forEach(m => {
          const mVal = m.year * 100 + m.monthIdx;
          let bestLog: any = null; let maxLogVal = 0;
          itemLogs.forEach(log => {
            const val = getYearMonthVal(log.fromDate || log.createdAt);
            let isValid = val <= mVal;
            if (isValid && log.toDate) {
              const toVal = getYearMonthVal(log.toDate);
              if (mVal > toVal) isValid = false;
            }
            if (isValid && val >= maxLogVal) { bestLog = log; maxLogVal = val; }
          });
          monthsData[m.name] = bestLog;
        });

        let nextYear = qDef.year; let nextQIndex = qDef.qIndex + 1;
        if (nextQIndex > 4) { nextQIndex = 1; nextYear += 1; }
        const nextQuarterStartVal = nextYear * 100 + (nextQIndex * 3 - 3);
        const currentQuarterStartVal = qDef.year * 100 + (qDef.qIndex * 3 - 3);
        let bestRevLog: any = null; let maxRevLogVal = 0; let prevRevLog: any = null; let maxPrevRevLogVal = 0;
        itemLogs.forEach(log => {
          const val = getYearMonthVal(log.fromDate || log.createdAt);
          
          let isValid = val <= nextQuarterStartVal;
          if (isValid && log.toDate) {
            const toVal = getYearMonthVal(log.toDate);
            if (toVal < nextQuarterStartVal) isValid = false;
          }
          if (isValid && val >= maxRevLogVal) { bestRevLog = log; maxRevLogVal = val; }
          
          let isPrevValid = val <= currentQuarterStartVal;
          if (isPrevValid && log.toDate) {
            const toVal = getYearMonthVal(log.toDate);
            if (toVal < currentQuarterStartVal) isPrevValid = false;
          }
          if (isPrevValid && val >= maxPrevRevLogVal) { prevRevLog = log; maxPrevRevLogVal = val; }
        });
        finalQuarters[qDef.quarterStr] = { months: monthsData, revision: bestRevLog, prevRevision: prevRevLog };
      });
      return { ...g, quarters: finalQuarters };
    });

    if (searchTerm.trim()) {
      const lower = searchTerm.toLowerCase();
      return finalGroups.filter(g =>
        (g.foreignName && g.foreignName.toLowerCase().includes(lower)) ||
        (g.castingCode && g.castingCode.toLowerCase().includes(lower)) ||
        (g.itemDescription && g.itemDescription.toLowerCase().includes(lower)) ||
        (g.vendor && g.vendor.toLowerCase().includes(lower)) ||
        (g.grade && g.grade.toLowerCase().includes(lower)) ||
        (g.key && g.key.toLowerCase().includes(lower))
      );
    }
    return finalGroups;
  }, [history, quartersList, searchTerm, mode]);

  const thClass = "px-3 py-2 border border-gray-300 text-[13px] font-bold text-gray-900 bg-white whitespace-nowrap";
  const hasActiveFilter = castingCodeFilter || vendorFilter || customerFilter || startYear !== currentYear || startQuarter !== currentQuarter;

  const resetFilters = () => { setCastingCodeFilter(''); setVendorFilter(''); setCustomerFilter(''); setStartYear(currentYear); setStartQuarter(currentQuarter); };

  const revDiff = (curr: number | undefined, prev: number | undefined) => {
    if (curr === undefined || curr === null) return '-';
    const c = Number(curr); const p = prev !== undefined && prev !== null ? Number(prev) : 0;
    const d = c - p; return d === 0 ? '-' : d > 0 ? `+${d.toFixed(2)}` : `${d.toFixed(2)}`;
  };

  return (
    <div className="flex-1 flex flex-col min-h-0 bg-[#F3F4F6] overflow-hidden">
      <div className="bg-white border-b border-gray-200 relative z-50 shrink-0">
        <div className="px-8 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="flex items-baseline gap-3">
              <h1 className="text-xl font-bold text-gray-900 tracking-wide uppercase">{mode === 'vendor' ? 'Vendor Price History' : 'Customer Price History'}</h1>
              <span className="text-sm text-gray-500 font-medium">({groupedData.length} records)</span>
            </div>
            <div className="flex items-center bg-gray-100 rounded-lg p-1 gap-1">
              {(['vendor', 'customer'] as const).map(m => (
                <button key={m} onClick={() => setMode(m)}
                  className={`px-4 py-1.5 rounded-md text-sm font-semibold transition-all duration-200 capitalize ${mode === m ? 'bg-white text-gray-900 shadow-sm border border-gray-200' : 'text-gray-500 hover:text-gray-700'}`}>
                  {m}
                </button>
              ))}
            </div>
          </div>
          <div className="flex items-center gap-3 flex-wrap">
            <SearchableSelect value={castingCodeFilter} onChange={setCastingCodeFilter} options={castingCodes} placeholder="All Casting Codes" className="w-[180px]" style={{ backgroundColor: '#ffffff' }} />
            {mode === 'vendor' ? (
              <SearchableSelect value={vendorFilter} onChange={setVendorFilter} options={vendorFiltersData.vendors.map(v => ({ value: v.id, label: v.name || v.id }))} placeholder="All Vendors" className="w-[200px]" style={{ backgroundColor: '#ffffff' }} />
            ) : (
              <SearchableSelect value={customerFilter} onChange={setCustomerFilter} options={customerFiltersData.customers.map(c => ({ value: c.code, label: c.name }))} placeholder="All Customers" className="w-[200px]" style={{ backgroundColor: '#ffffff' }} />
            )}
            <select value={startYear} onChange={e => setStartYear(Number(e.target.value))} className="h-[38px] px-3 rounded-lg border text-sm focus:outline-none focus:ring-1 bg-white" style={{ borderColor: BRAND.BORDER } as React.CSSProperties}>
              {[2025, 2026, 2027, 2028].map(y => <option key={y} value={y}>{y}</option>)}
            </select>
            <select value={startQuarter} onChange={e => setStartQuarter(Number(e.target.value))} className="h-[38px] px-3 rounded-lg border text-sm focus:outline-none focus:ring-1 bg-white" style={{ borderColor: BRAND.BORDER } as React.CSSProperties}>
              {[1, 2, 3, 4].map(q => <option key={q} value={q}>Quarter {q}</option>)}
            </select>
            {hasActiveFilter && (
              <button onClick={resetFilters} className="h-[38px] inline-flex items-center gap-2 px-3 py-2 text-sm font-semibold text-red-700 bg-red-50 border border-red-200 rounded-lg shadow-sm hover:bg-red-100 transition-all duration-200">
                <svg className="w-4 h-4 text-red-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6L6 18M6 6l12 12" /></svg>
                <span>Reset</span>
              </button>
            )}
            <div className="relative">
              <svg style={{ position: 'absolute', left: 10, top: '50%', transform: 'translateY(-50%)', color: '#9CA3AF', pointerEvents: 'none' }} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>
              <input type="text" placeholder="Search..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-[200px] h-[38px] pl-9 pr-3 rounded-lg border text-sm focus:outline-none focus:ring-1 bg-white" style={{ borderColor: BRAND.BORDER, '--tw-ring-color': BRAND.RED } as React.CSSProperties} />
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 p-8 space-y-6 flex flex-col min-h-0 overflow-hidden">
        <div className="bg-white shadow rounded-lg flex-1 flex flex-col min-h-0 overflow-hidden border border-gray-200">
          <div className="flex-1 overflow-auto rounded-lg">
            <table className="w-full text-xs text-left border-collapse min-w-[2000px]">
              <thead className="sticky top-0 z-30 shadow-sm bg-white">
                <tr>
                  {mode === 'vendor' ? (
                    <>
                      <th rowSpan={3} className={`${thClass} min-w-[150px] sticky left-0 z-40 bg-white`}>Foreign Name</th>
                      <th rowSpan={3} className={`${thClass} min-w-[100px] sticky left-[150px] z-40 bg-white`}>Casting Code</th>
                      <th rowSpan={3} className={`${thClass} min-w-[150px]`}>Item Description</th>
                      <th rowSpan={3} className={`${thClass} min-w-[120px]`}>Vendor</th>
                      <th rowSpan={3} className={`${thClass} min-w-[100px]`}>Grade</th>
                    </>
                  ) : (
                    <>
                      <th rowSpan={3} className={`${thClass} min-w-[150px] sticky left-0 z-40 bg-white`}>Customer Name</th>
                      <th rowSpan={3} className={`${thClass} min-w-[100px] sticky left-[150px] z-40 bg-white`}>Casting Code</th>
                      <th rowSpan={3} className={`${thClass} min-w-[150px]`}>Item Description</th>
                      <th rowSpan={3} className={`${thClass} min-w-[90px]`}>Dom/Export</th>
                      <th rowSpan={3} className={`${thClass} min-w-[100px]`}>Grade</th>
                    </>
                  )}
                  {quartersList.map(q => {
                    const monthsColSpan = q.months.reduce((sum, m, mIdx) => {
                      if (mIdx === 2) return sum + 3; // The third month (September) has no splits
                      return sum + (expandedMonths.has(m.name) ? 7 : 3);
                    }, 0);
                    return (
                      <React.Fragment key={`h1-${q.quarterStr}`}>
                        <th colSpan={monthsColSpan} className="px-3 py-2 border border-gray-300 text-[13px] font-bold text-white bg-green-600 text-center whitespace-nowrap">
                          {q.quarterStr}
                        </th>
                        <th colSpan={4} rowSpan={2} className="px-3 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 bg-yellow-400 text-center whitespace-nowrap min-w-[240px]">
                          {q.revisionStr}
                        </th>
                      </React.Fragment>
                    );
                  })}
                </tr>
                <tr>
                  {quartersList.map(q => (
                    <React.Fragment key={`h2-${q.quarterStr}`}>
                      {q.months.map((m, idx) => {
                        const bgColors = ["bg-orange-100", "bg-pink-100", "bg-blue-100"];
                        const isExpanded = expandedMonths.has(m.name);
                        const canExpand = idx < 2; // only first two months (e.g. July, August) can expand
                        return (
                          <th key={m.name} colSpan={isExpanded && canExpand ? 7 : 3} className={`px-2 py-2 border border-gray-300 text-[13px] font-bold text-gray-900 text-center whitespace-nowrap ${bgColors[idx]}`}>
                            <div className="flex items-center justify-center gap-1.5">
                              <span>{m.name}</span>
                              {canExpand && (
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setExpandedMonths(prev => {
                                      const next = new Set(prev);
                                      if (next.has(m.name)) next.delete(m.name);
                                      else next.add(m.name);
                                      return next;
                                    });
                                  }}
                                  className="px-1 py-0.5 text-[9px] font-bold text-red-700 bg-white hover:bg-red-50 border border-red-300 rounded shadow-sm cursor-pointer transition-colors duration-150"
                                  title={isExpanded ? "Collapse MMR Columns" : "Expand MMR Columns"}
                                >
                                  {isExpanded ? "◀ MMR" : "▶ MMR"}
                                </button>
                              )}
                            </div>
                          </th>
                        );
                      })}
                    </React.Fragment>
                  ))}
                </tr>
                <tr>
                  {quartersList.map(q => (
                    <React.Fragment key={`h3-${q.quarterStr}`}>
                      {q.months.map((m, idx) => {
                        const isExpanded = expandedMonths.has(m.name);
                        const canExpand = idx < 2;
                        return (
                          <React.Fragment key={`h3m-${m.name}`}>
                            <th className="px-2 py-2 border border-gray-300 text-[13px] font-bold text-gray-900 text-center bg-white whitespace-nowrap">{mode === 'customer' ? 'Cast Wt' : 'Rm Weight'}</th>
                            <th className="px-2 py-2 border border-gray-300 text-[13px] font-bold text-gray-900 text-center bg-white whitespace-nowrap">{mode === 'customer' ? 'Cast Rate/Kg' : 'Revised Rate/Kg'}</th>
                            <th className="px-2 py-2 border border-gray-300 text-[13px] font-bold text-gray-900 text-center bg-white whitespace-nowrap">{mode === 'customer' ? 'Casting Price' : 'Revised Price'}</th>
                            {isExpanded && canExpand && (
                              <>
                                <th className="px-2 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 text-center bg-yellow-300 whitespace-nowrap">MMR</th>
                                <th className="px-2 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 text-center bg-yellow-300 whitespace-nowrap">RO</th>
                                <th className="px-2 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 text-center bg-yellow-300 whitespace-nowrap">Cons</th>
                                <th className="px-2 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 text-center bg-yellow-300 whitespace-nowrap">Extra</th>
                              </>
                            )}
                          </React.Fragment>
                        );
                      })}
                      {/* Quarterly split headers */}
                      <th className="px-2 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 text-center bg-yellow-300 whitespace-nowrap">MMR</th>
                      <th className="px-2 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 text-center bg-yellow-300 whitespace-nowrap">RO</th>
                      <th className="px-2 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 text-center bg-yellow-300 whitespace-nowrap">Cons</th>
                      <th className="px-2 py-2 border border-gray-400 text-[13px] font-bold text-gray-900 text-center bg-yellow-300 whitespace-nowrap">Extra</th>
                    </React.Fragment>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 bg-white">
                {(() => {
                  const totalCols = 5 + quartersList.reduce((sum, q) => sum + 4 + q.months.reduce((mSum, m, mIdx) => {
                    if (mIdx === 2) return mSum + 3;
                    return mSum + (expandedMonths.has(m.name) ? 7 : 3);
                  }, 0), 0);
                  if (loading) {
                    return <tr><td colSpan={totalCols} className="px-4 py-8 text-center text-gray-500 text-sm">Loading...</td></tr>;
                  }
                  if (groupedData.length === 0) {
                    return (
                      <tr>
                        <td colSpan={totalCols} className="px-4 py-8 text-center text-gray-500 text-sm">
                          {mode === 'customer' ? 'No customer price history found. History is recorded when customer pricing batches are approved.' : 'No price history found.'}
                        </td>
                      </tr>
                    );
                  }
                  return groupedData.map((row) => (
                    <tr key={row.key} className="hover:bg-blue-50 transition-colors">
                      <td className="px-3 py-2 border border-gray-200 font-medium text-gray-900 bg-white sticky left-0 z-20">{row.foreignName}</td>
                      <td className="px-3 py-2 border border-gray-200 text-gray-600 bg-white sticky left-[150px] z-20">{row.castingCode}</td>
                      <td className="px-3 py-2 border border-gray-200 text-gray-600 truncate max-w-[200px]" title={row.itemDescription}>{row.itemDescription}</td>
                      {mode === 'vendor' ? (
                        <td className="px-3 py-2 border border-gray-200 text-gray-600 truncate max-w-[150px]">{row.vendor}</td>
                      ) : (
                        <td className="px-3 py-2 border border-gray-200 text-gray-600 text-center">
                          <span className={`inline-block px-2 py-0.5 rounded text-[11px] font-semibold ${
                            row.domesticExport === 'Domestic' ? 'bg-green-100 text-green-700' :
                            row.domesticExport === 'Export' ? 'bg-blue-100 text-blue-700' :
                            row.domesticExport === 'Labour' ? 'bg-purple-100 text-purple-700' :
                            'bg-gray-100 text-gray-600'
                          }`}>{row.domesticExport || '-'}</span>
                        </td>
                      )}
                      <td className="px-3 py-2 border border-gray-200 text-gray-600">{row.grade}</td>
                      {quartersList.map(q => {
                        const qData = row.quarters[q.quarterStr];
                        return (
                          <React.Fragment key={`data-${row.key}-${q.quarterStr}`}>
                            {q.months.map((m, idx) => {
                              const mData = qData?.months[m.name];
                              const bgColors = ["bg-orange-50/30", "bg-pink-50/30", "bg-blue-50/30"];
                              const wt = mode === 'customer' ? mData?.newCastWeight : mData?.rmWeight;
                              const rate = mode === 'customer' ? mData?.newCastRate : mData?.newRatePerKg;
                              const isExpanded = expandedMonths.has(m.name);
                              const canExpand = idx < 2;
                              return (
                                <React.Fragment key={`data-${row.key}-${m.name}`}>
                                  <td className={`px-2 py-2 border border-gray-200 text-center font-mono text-gray-700 ${bgColors[idx]}`}>{wt != null ? Number(wt).toFixed(2) : '-'}</td>
                                  <td className={`px-2 py-2 border border-gray-200 text-center font-mono text-gray-700 font-medium ${bgColors[idx]}`}>{rate != null ? `₹${Number(rate).toFixed(2)}` : '-'}</td>
                                  <td className={`px-2 py-2 border border-gray-200 text-center font-mono text-gray-900 font-semibold ${bgColors[idx]}`}>
                                    {mData ? (
                                      mode === 'customer'
                                        ? (wt != null && rate != null ? `₹${(Number(wt) * Number(rate)).toFixed(2)}` : '-')
                                        : (wt != null && rate != null ? `₹${(Number(wt) * Number(rate)).toFixed(2)}` : mData.newPrice != null ? `₹${Number(mData.newPrice).toFixed(2)}` : '-')
                                    ) : '-'}
                                  </td>
                                  {isExpanded && canExpand && (() => {
                                    const nextMonthDef = q.months[idx + 1];
                                    const mDataNext = qData?.months[nextMonthDef.name];
                                    let showSplits = false;
                                    if (mDataNext) {
                                      const logVal = getYearMonthVal(mDataNext.fromDate || mDataNext.createdAt);
                                      const nextMonthVal = nextMonthDef.year * 100 + nextMonthDef.monthIdx;
                                      showSplits = logVal === nextMonthVal;
                                    }
                                    if (row.castingCode.includes('20mncr5')) {
                                      console.log(`[DEBUG 20mncr5] idx=${idx}, m.name=${m.name}, nextMonthDef.name=${nextMonthDef.name}, logVal=${getYearMonthVal(mDataNext?.fromDate || mDataNext?.createdAt)}, nextMonthVal=${nextMonthDef.year * 100 + nextMonthDef.monthIdx}, mDataNext=${JSON.stringify(mDataNext)}, showSplits=${showSplits}`);
                                    }
                                    return (
                                      <>
                                        <td className="px-2 py-2 border border-gray-300 text-center font-mono text-gray-900 bg-yellow-50/50">{showSplits ? revDiff(mDataNext?.newMmr, mDataNext?.oldMmr) : '-'}</td>
                                        <td className="px-2 py-2 border border-gray-300 text-center font-mono text-gray-900 bg-yellow-50/50">{showSplits ? revDiff(mDataNext?.newCoating, mDataNext?.oldCoating) : '-'}</td>
                                        <td className="px-2 py-2 border border-gray-300 text-center font-mono text-gray-900 bg-yellow-50/50">{showSplits ? revDiff(mDataNext?.newConsumables, mDataNext?.oldConsumables) : '-'}</td>
                                        <td className="px-2 py-2 border border-gray-300 text-center font-mono text-gray-900 bg-yellow-50/50">{showSplits ? revDiff(mDataNext?.newExtra, mDataNext?.oldExtra) : '-'}</td>
                                      </>
                                    );
                                  })()}
                                </React.Fragment>
                              );
                            })}
                            {/* Quarterly split values */}
                            <td className="px-2 py-2 border border-gray-300 text-center font-mono text-gray-900 bg-yellow-50/50">{revDiff(qData?.revision?.newMmr, qData?.revision?.oldMmr)}</td>
                            <td className="px-2 py-2 border border-gray-300 text-center font-mono text-gray-900 bg-yellow-50/50">{revDiff(qData?.revision?.newCoating, qData?.revision?.oldCoating)}</td>
                            <td className="px-2 py-2 border border-gray-300 text-center font-mono text-gray-900 bg-yellow-50/50">{revDiff(qData?.revision?.newConsumables, qData?.revision?.oldConsumables)}</td>
                            <td className="px-2 py-2 border border-gray-300 text-center font-mono text-gray-900 bg-yellow-50/50">{revDiff(qData?.revision?.newExtra, qData?.revision?.oldExtra)}</td>
                          </React.Fragment>
                        );
                      })}
                    </tr>
                  ));
                })()}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};
